import * as THREE from './vendor/three.module.js';
export function batchStatic(scene){const before=scene.children.filter(m=>m.isMesh).length;const groups=new Map();for(const m of [...scene.children]){if(!m.isMesh||m.material.transparent||m.material.map)continue;const k=JSON.stringify([m.geometry.type,m.geometry.parameters,m.material.type,m.material.color?.getHex()]);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(m);}for(const list of groups.values()){if(list.length<3)continue;const mesh=new THREE.InstancedMesh(list[0].geometry,list[0].material,list.length);list.forEach((m,i)=>{m.updateMatrix();mesh.setMatrixAt(i,m.matrix);scene.remove(m);});mesh.computeBoundingSphere();scene.add(mesh);}scene.userData.batch={before,after:scene.children.filter(m=>m.isMesh).length};}
